from pathlib import Path
import json,geopandas as g,numpy as np,shapely
from shapely.strtree import STRtree
out=Path('data/user_shanghai');city=g.read_file('data/raw/shanghai_boundary.geojson').to_crs(32651).geometry.union_all();shapely.prepare(city);classes=['footway','path','pedestrian','steps'];a=g.read_file(out/'national_roads.gpkg').to_crs(32651);b=g.read_file('data/raw/osm/gis_osm_roads_free_1.shp').to_crs(32651);a=a[a.fclass.isin(classes)];b=b[b.fclass.isin(classes)];a=a[shapely.intersects(city,a.geometry.array)].copy();b=b[shapely.intersects(city,b.geometry.array)];tree=STRtree(b.geometry.to_numpy());pts=shapely.line_interpolate_point(a.geometry.array,.5,normalized=True);_,dist=tree.query_nearest(pts,return_distance=True,all_matches=False);a['distance_to_2026_m']=dist;extra=a[dist>10].copy();extra['explicit_bridge_or_tunnel']=(extra.bridge=='T')|(extra.tunnel=='T');extra.to_file(out/'pedestrian_review_candidates.gpkg',driver='GPKG');lens=shapely.length(a.geometry.array);m={'2025_pedestrian_ways':len(a),'2026_pedestrian_ways':len(b),'weighted_midpoint_share_within_2m':float(lens[dist<2].sum()/lens.sum()),'weighted_midpoint_share_within_10m':float(lens[dist<10].sum()/lens.sum()),'review_candidates':len(extra),'candidate_explicit_bridge_or_tunnel':int(extra.explicit_bridge_or_tunnel.sum()),'note':'Candidates not automatically considered usable crossings; review current status and access.'};(out/'pedestrian_audit.json').write_text(json.dumps(m,ensure_ascii=False,indent=2));print(json.dumps(m,indent=2))
